-- 3. Seed Characters
INSERT INTO public.characters (id, name, slug, biography, stats_json, featured_image, status, created_at, updated_at) VALUES
  ('c1111111-1111-1111-1111-111111111111', 'Lucia', 'lucia', 'Lucia is one of the dual protagonists of Grand Theft Auto VI. She is a sharp, experienced, and highly ambitious criminal operating within the state of Leonida. Fresh off a stint in prison as shown in Trailer 1, Lucia brings street-smart pragmatism and high-stakes leadership to her partnership with Jason. Her backstory is rooted in local Vice City crew networks, giving her deep connections and knowledge of the state''s lucrative smuggling pipelines. Lucia represents a modern noir criminal: fiercely loyal, strategic, and willing to push boundaries to establish her empire.', '{"role": "Protagonist", "status": "Active", "affiliation": "Jason / Convenience Crews", "voice_actor": "TBA", "first_appearance": "Trailer 1"}'::jsonb, '/og-image.jpg', 'published', now(), now()),
  ('c2222222-2222-2222-2222-222222222222', 'Jason', 'jason', 'Jason is the second dual protagonist of Grand Theft Auto VI, partner in crime and companion to Lucia. Characterized by a more reserved but intensely action-oriented demeanor, Jason is a capable driver, marksman, and enforcer. His background involves regional drifter circles and automotive operations, giving him exceptional tactical mobility. Jason''s dynamic with Lucia forms the emotional and narrative core of the game, blending a high-stakes romance with organized crime heists. Highly protective and pragmatic, he acts as the tactical muscle of their convenience crew operations.', '{"role": "Protagonist", "status": "Active", "affiliation": "Lucia / Convenience Crews", "voice_actor": "TBA", "first_appearance": "Trailer 1"}'::jsonb, '/og-image.jpg', 'published', now(), now()),
  ('c3333333-3333-3333-3333-333333333333', 'Uncle Sam', 'uncle-sam', 'Uncle Sam is a colorful, deeply eccentric local patriarch operating a smuggling barge network across the Leonida Grasslands. Known for his wild theories, extreme patriotism, and deep connection to regional black-market weapons, he is a key contact for Lucia and Jason in their quest to obtain military-grade firepower. Uncle Sam represents the quintessential wild Florida/Leonida culture, bridging regional side-activities with major narrative missions.', '{"role": "Supporting Ally", "status": "Active", "affiliation": "Grasslands Smugglers", "voice_actor": "TBA", "first_appearance": "Speculated / Leak"}'::jsonb, '/og-image.jpg', 'published', now(), now())
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, biography = EXCLUDED.biography, stats_json = EXCLUDED.stats_json, updated_at = now();

