INSERT INTO public.map_locations (id, name, slug, description, category, x_coord, y_coord, image, status, related_article_ids, view_count, created_at) VALUES
  ('a1111111-1111-1111-1111-111111111111', 'Vice City Beach', 'vice-city-beach', 'A sprawling coastal metropolis strip lined with high-end neon hotels, dense tourist populations, and pristine sand dunes. Based on Miami Beach.', 'landmark', 72.5, 48.2, '/og-image.jpg', 'confirmed', '[]'::jsonb, 150, now()),
  ('a2222222-2222-2222-2222-222222222222', 'Port Gellhorn', 'port-gellhorn', 'A key industrial and port town situated on the western edges of the map, featuring shipping yards, local convenience stores, and dirt track racing areas.', 'city', 25.4, 62.1, '/og-image.jpg', 'confirmed', '[]'::jsonb, 95, now()),
  ('a3333333-3333-3333-3333-333333333333', 'Grasslands', 'grasslands', 'The vast muddy marshlands and swamp networks located in central Leonida, home to diverse wildlife and extreme off-road driving terrain.', 'poi', 50.0, 55.0, '/og-image.jpg', 'confirmed', '[]'::jsonb, 67, now()),
  ('a4444444-4444-4444-4444-444444444444', 'Leonida Keys', 'leonida-keys', 'A scenic chain of islands spanning the southern tip of the state, connected by massive highway bridges. Home to boating, fishing, and smuggling pipelines.', 'landmark', 85.0, 88.0, '/og-image.jpg', 'confirmed', '[]'::jsonb, 120, now()),
  ('a5555555-5555-5555-5555-555555555555', 'Kelly County', 'kelly-county', 'A rural inland county containing trailer parks, farmsteads, and massive dirt-track mud pits for monster truck rallies.', 'city', 32.8, 38.2, '/og-image.jpg', 'confirmed', '[]'::jsonb, 42, now()),
  ('a6666666-6666-6666-6666-666666666666', 'Lake Leonida', 'lake-leonida', 'The largest freshwater body of water in the state, bordered by dense pine forests and recreational camping areas.', 'poi', 45.6, 22.4, '/og-image.jpg', 'confirmed', '[]'::jsonb, 88, now()),
  ('a7777777-7777-7777-7777-777711111111', 'Vice City Marina', 'vice-city-marina', 'A luxury docking basin where billionaires park superyachts, housing speedboat dealerships and high-stakes white-collar heists.', 'poi', 68.2, 58.7, '/og-image.jpg', 'confirmed', '[]'::jsonb, 104, now()),
  ('a8888888-8888-8888-8888-888811111111', 'Ocean Drive', 'ocean-drive', 'The iconic beachfront strip lit entirely by bright pastel neon signages, fast sports cars, and elite nightclubs.', 'landmark', 74.1, 50.5, '/og-image.jpg', 'confirmed', '[]'::jsonb, 210, now()),
  ('a9999999-9999-9999-9999-999911111111', 'Stockyard', 'stockyard', 'An industrial railway yard and cargo container depot where heavy transport freight trains pass through. Highly secured.', 'poi', 61.2, 41.3, '/og-image.jpg', 'confirmed', '[]'::jsonb, 54, now()),
  ('a1010101-1010-1010-1010-101011111111', 'Wanship', 'wanship', 'A shipping channel and suburban logistics hub near the state line, hosting container ports and truck stops.', 'city', 18.9, 31.2, '/og-image.jpg', 'confirmed', '[]'::jsonb, 39, now()),
  ('a1212121-1212-1212-1212-121211111111', 'Hamlet', 'hamlet', 'A quiet suburban community of neat houses and winding waterways, contrasting with the chaotic neon of the city center.', 'city', 42.1, 78.5, '/og-image.jpg', 'confirmed', '[]'::jsonb, 79, now()),
  ('a1313131-1313-1313-1313-131311111111', 'Fairyland', 'fairyland', 'An abandoned amusement park theme park, rumored to host hidden weapons and developer Easter eggs.', 'easter-egg', 55.3, 15.6, '/og-image.jpg', 'speculated', '[]'::jsonb, 115, now())
